<dialog class="admin-reservation-dialog" id="reservation-dialogue"><button type="button" class="reservation-dialog-close" aria-label="Fermer">×</button><section id="reservation-detail-view"><p class="admin-reservation-dialog-eyebrow">FICHE RÉSERVATION</p><h3 id="detail-reservation-name"></h3><p id="detail-reservation-email"></p><dl><div><dt>Activité</dt><dd id="detail-reservation-title"></dd></div><div><dt>Type</dt><dd id="detail-reservation-type"></dd></div><div><dt>Date et heure</dt><dd id="detail-reservation-date"></dd></div><div><dt>Salle</dt><dd id="detail-reservation-room"></dd></div><div><dt>Coach</dt><dd id="detail-reservation-coach"></dd></div><div><dt>Statut</dt><dd id="detail-reservation-status"></dd></div><div><dt>Places prises</dt><dd id="detail-reservation-spots"></dd></div></dl></section><form method="post" id="modifier-reservation-form" hidden><?= champ_csrf() ?><input type="hidden" name="action" value="modifier_reservation_admin"><input type="hidden" name="reservation" id="dialog-reservation-id"><input type="hidden" name="semaine" value="<?= e($semaineReservationsAdmin) ?>"><h3>Modifier la réservation</h3><label>Choisir un autre cours<select name="activite" id="dialog-reservation-course" required><option value="">Sélectionner un cours</option><?php foreach ($activitesDisponiblesReservation as $activiteOption): $completOption = (int) $activiteOption['places_prises'] >= (int) $activiteOption['capacite_max']; ?><option value="<?= (int) $activiteOption['Numactivite'] ?>" data-complet="<?= $completOption ? '1' : '0' ?>" <?= $completOption ? 'disabled' : '' ?>><?= e($activiteOption['titre']) ?> · <?= date('d/m H:i', strtotime($activiteOption['date_heure_debut'])) ?> · <?= e($activiteOption['nomsalle']) ?> (<?= (int) $activiteOption['places_prises'] ?>/<?= (int) $activiteOption['capacite_max'] ?>)</option><?php endforeach; ?></select></label><button type="submit">Enregistrer le changement</button></form><form method="post" id="ajouter-reservation-form" hidden><?= champ_csrf() ?><input type="hidden" name="action" value="ajouter_reservation_admin"><input type="hidden" name="semaine" value="<?= e($semaineReservationsAdmin) ?>"><h3>Ajouter une réservation</h3><label>Adhérent<select name="adherent" required><option value="">Choisir un adhérent</option><?php foreach ($adherentsReservationsAdmin as $adherentOption): ?><option value="<?= (int) $adherentOption['NumUsers'] ?>"><?= e($adherentOption['prenomUsers'] . ' ' . $adherentOption['nomUsers'] . ' · ' . $adherentOption['mailUsers']) ?></option><?php endforeach; ?></select></label><label>Cours<select name="activite" required><option value="">Choisir un cours disponible</option><?php foreach ($activitesDisponiblesReservation as $activiteOption): if ((int) $activiteOption['places_prises'] >= (int) $activiteOption['capacite_max']) continue; ?><option value="<?= (int) $activiteOption['Numactivite'] ?>"><?= e($activiteOption['titre']) ?> · <?= date('d/m H:i', strtotime($activiteOption['date_heure_debut'])) ?> · <?= e($activiteOption['nomsalle']) ?> (<?= (int) $activiteOption['places_prises'] ?>/<?= (int) $activiteOption['capacite_max'] ?>)</option><?php endforeach; ?></select></label><button type="submit">Enregistrer la réservation</button></form></dialog>

<script>
document.addEventListener('DOMContentLoaded', () => {
  const rows = [...document.querySelectorAll('[data-reservation-row]')];
  const filters = [document.getElementById('filtre-reservation-activite'),document.getElementById('filtre-reservation-salle'),document.getElementById('filtre-reservation-statut')];
  const search = document.getElementById('recherche-reservation'); const empty = document.getElementById('reservations-filtre-vide');
  const filterRows = () => { const selected=filters.map(f=>f?.value||''); const q=(search?.value||'').trim().toLocaleLowerCase('fr'); let shown=0; rows.forEach(row=>{const visible=(!selected[0]||row.dataset.type===selected[0])&&(!selected[1]||row.dataset.room===selected[1])&&(!selected[2]||row.dataset.status===selected[2])&&row.dataset.search.includes(q);row.hidden=!visible;if(visible)shown++;});if(empty)empty.hidden=shown>0;};
  filters.forEach(f=>f?.addEventListener('change',filterRows));search?.addEventListener('input',filterRows);
  const dialog=document.getElementById('reservation-dialogue'); const detail=document.getElementById('reservation-detail-view'); const editForm=document.getElementById('modifier-reservation-form'); const addForm=document.getElementById('ajouter-reservation-form'); const courseSelect=document.getElementById('dialog-reservation-course');
  document.querySelectorAll('[data-reservation-view]').forEach(button=>button.addEventListener('click',()=>{detail.hidden=false;editForm.hidden=true;addForm.hidden=true;const d=button.dataset;document.getElementById('detail-reservation-name').textContent=d.name;document.getElementById('detail-reservation-email').textContent=d.email;document.getElementById('detail-reservation-title').textContent=d.title;document.getElementById('detail-reservation-type').textContent=d.type;document.getElementById('detail-reservation-date').textContent=d.start+' – '+d.end;document.getElementById('detail-reservation-room').textContent=d.roomName;document.getElementById('detail-reservation-coach').textContent=d.coach;document.getElementById('detail-reservation-status').textContent=d.statusLabel;document.getElementById('detail-reservation-spots').textContent=d.spots;dialog.showModal();}));
  document.querySelectorAll('[data-reservation-edit]').forEach(button=>button.addEventListener('click',()=>{detail.hidden=true;editForm.hidden=false;addForm.hidden=true;document.getElementById('dialog-reservation-id').value=button.dataset.id;courseSelect.value='';courseSelect.querySelectorAll('option[data-complet]').forEach(option=>option.disabled=option.dataset.complet==='1');const current=courseSelect.querySelector(`[value="${button.dataset.currentCourse}"]`);if(current)current.disabled=false;dialog.showModal();}));
  document.querySelector('[data-reservation-new]')?.addEventListener('click',event=>{event.preventDefault();detail.hidden=true;editForm.hidden=true;addForm.hidden=false;dialog.showModal();});
  document.querySelector('.reservation-dialog-close')?.addEventListener('click',()=>dialog.close());
  document.querySelectorAll('.admin-reservation-action-form').forEach(form=>form.addEventListener('submit',event=>{const button=form.querySelector('[data-confirmation]');if(button&&!window.confirm(button.dataset.confirmation))event.preventDefault();}));
});
</script>
